# =============================================================================
# 09_dag_negative_controls_trajectories.R — Final DAG (edges checked against dagitty), 6 h / 12 h negative
#   controls in the primary population, creatinine and urea trajectories,
#   figure legends generated by the single text formatter. -> output/final/
# Usage: Rscript scripts/09_dag_negative_controls_trajectories.R
# =============================================================================
options(warn = 1, scipen = 10, v31.cores = 8L)
suppressPackageStartupMessages({ library(data.table); library(glmnet); library(ggplot2) })
PKG_AVAILABLE <- function(p) isTRUE(requireNamespace(p, quietly = TRUE))
invisible(lapply(c("mice", "cobalt", "jsonlite", "survival", "patchwork", "pROC", "dagitty"), loadNamespace))
IN <- "output/analysis"; OUT <- "output/final"
TAB <- function(f) file.path(OUT, "tables", f); FIG <- function(f) file.path(OUT, "figures", f)
FAST <- Sys.getenv("PIPELINE_FAST") == "1"; B_EARLY <- if (FAST) 5L else 200L; B_BROAD <- if (FAST) 5L else 50L; B_TRAJ <- if (FAST) 5L else 200L
T_START <- Sys.time()
for (f in c("R/01_paths_and_io.R", "R/02_codebooks.R", "R/20_bootstrap.R", "R/30_results_master.R",
            "R/50_master_cohort.R", "R/51_analysis_cohort.R", "R/52_estimation.R", "R/53_extract.R", "R/56_results_tables.R",
            "R/71_registry.R", "R/74_dag.R", "R/75_positivity_flow.R", "R/77_tables_figs.R", "R/78_reporting.R",
            "R/80_robustness.R", "R/81_exposure_flow_cif.R", "R/82_dag_figure.R", "R/83_text_formatter.R")) source(f)
creat_dt <- readRDS("output/extraction/derived_data/creatinine_all.rds")
spec <- readRDS(file.path(IN, "derived_data", "analysis_spec_v32.rds")); PS <- spec$PS; METHOD <- spec$FINAL_METHODS

cat("=== C.0 Registre, données gelées, results_master v3.3 (phase B) ===\n")
master <- setup_registry_v32(readRDS(file.path(IN, "derived_data", "master_v32.rds")))$master; setkey(master, hadm_id)
reg32 <- fread(file.path(IN, "tables", "n_by_analysis_v32.csv"))
get_analysis_cohort(list(id = "early_eligible", parent = "eligible_2arm", filter = EARLY_FILTER_V32, label = reg32[cohort_id == "early_eligible", label]), master)
# C2 : patients avec >= 1 créatinine dans ]T0 ; T0+6 h] ET >= 1 dans ]T0+6 h ; T0+12 h]
cw <- merge(creat_dt[, .(hadm_id, charttime)], master[, .(hadm_id, T0)], by = "hadm_id")[, h := as.numeric(difftime(charttime, T0, units = "hours"))]
both <- cw[, .(w6 = any(h > 0 & h <= 6), w12 = any(h > 6 & h <= 12)), by = hadm_id][w6 & w12, hadm_id]
master[, nc_same_window := as.integer(hadm_id %in% both)]
for (p in c("early", "broad"))
  get_analysis_cohort(list(id = paste0(p, "_nc_same"), parent = p, filter = quote(nc_same_window == 1L & !is.na(early_creat_rise_6h) & !is.na(early_creat_rise_12h)),
                           label = paste0(p, ": creatinine measured in both (T0; T0+6 h] and (T0+6 h; T0+12 h] (negative controls, same population)")), master)
for (cid in setdiff(reg32$cohort_id, cohort_registry_table()$cohort_id)) .COHORT_REGISTRY_V31$rows[[cid]] <- reg32[cohort_id == cid]
IMP <- readRDS(file.path(IN, "derived_data", "mi_C_stratified_m20.rds"))$imp[seq_len(if (FAST) 2 else 20)]
D <- function(id) get_analysis_data(id, IMP)
RAW <- function(id) master[J(.COHORT_REGISTRY_V31$ids[[id]])]
M <- length(IMP)
rmt <- readRDS(file.path(OUT, "results", "results_master.rds"))
rmt <- rmt[!grepl("_nc_a(6|12)_same$", analysis_id)]   # relance idempotente
ADD <- function(id, est, cohort_id, role, outcome, description, ci_method, population, arm_stats) {
  tmp <- add_row_v31(rmt[0], id, est, cohort_id, phase = "V33", role = role, estimand = "ATO", outcome = outcome, description = description, comparator = "meropenem")
  set(tmp, 1L, "ci_method", ci_method); set(tmp, 1L, "population", population)
  for (k in names(arm_stats)) set(tmp, 1L, k, arm_stats[[k]])
  pc <- precision_cols_v32(est$rd_ci_low, est$rd_ci_high); for (k in names(pc)) set(tmp, 1L, k, pc[[k]])
  rmt <<- rbind(rmt, tmp, fill = TRUE)
}

cat("\n=== C1 DAG redessiné ===\n")
g <- build_dag_v32(); geo <- dag_geometry_v33(g); pdag <- plot_dag_v33(geo); qd <- qa_dag_v33(pdag, geo, g)
save_fig_v32(pdag, FIG("fig2_dag"), 24, 17)
unlink(FIG(c("efig_dag_detailed.png", "efig_dag_detailed.pdf")))   # remplacée par la table nœud -> variables (eTable)
fwrite(geo$edges[, .(from, to)], TAB("dag_edges_v33.csv")); str(qd)

cat("\n=== C2 Contrôles négatifs 6 h et 12 h dans la même population ===\n")
POPL <- c(early = "Early (primary)", broad = "Broad (secondary)")
for (p in names(POPL)) {
  cid <- paste0(p, "_nc_same"); dl <- D(cid); B <- if (p == "early") B_EARLY else B_BROAD
  for (oc in c(nc_a6 = "early_creat_rise_6h", nc_a12 = "early_creat_rise_12h")) {
    nm <- names(which(c(nc_a6 = "early_creat_rise_6h", nc_a12 = "early_creat_rise_12h") == oc))
    e <- ato_mi_v31(dl, PS, oc, METHOD[[p]], B = B, label = paste(cid, nm))
    ADD(paste0(p, "_negative_control_", nm, "_same"), e, cid, "NEGATIVE_CONTROL", oc,
        sprintf("%s: negative control, creatinine rise within %s h, same population for both windows (creatinine measured in (T0; T0+6 h] and (T0+6 h; T0+12 h]).",
                POPL[[p]], if (nm == "nc_a6") "6" else "12"),
        sprintf("Bootstrap SE within each of m=%d imputations (B=%d, PS re-fitted per replicate), Rubin's rules (Barnard-Rubin df)", M, B), POPL[[p]],
        enrich_arm_stats_v32(e, dl, oc))
  }
}
ncs <- rmt[grepl("negative_control_nc_a(6|12)", analysis_id), .(analysis_id, population, cohort_id, n, n_ptz, n_carb, events_ptz, events_comp, rd, rd_ci_low, rd_ci_high)]
ncs[, `:=`(window = fifelse(grepl("a6", analysis_id), "6 h", "12 h"), population_definition = fifelse(grepl("_same$", analysis_id), "same population (both windows measured)", "window-specific population"))]
fwrite(ncs, TAB("negative_controls_same_population_v33.csv")); print(ncs[, .(analysis_id, n, events_comp, rd = round(100 * rd, 2), lo = round(100 * rd_ci_low, 2), hi = round(100 * rd_ci_high, 2))])

cat("\n=== C3 Trajectoires : rapport urée/créatinine, restriction J5-J7 ===\n")
labs <- readRDS("output/extraction/derived_data/labs_long_v31.rds")
creat_vals <- creat_dt[, .(subject_id, hadm_id, charttime, value = creat_mgdl)]
bun_vals <- labs[itemid == LAB_ITEMS_V31$bun & valuenum > 0 & valuenum < 300, .(subject_id, hadm_id, charttime, value = valuenum)]
ratio_vals <- merge(bun_vals, creat_vals, by = c("subject_id", "hadm_id", "charttime"), suffixes = c("_bun", "_cr"))[value_cr > 0, .(subject_id, hadm_id, charttime, value = value_bun / value_cr)]
TR <- list(); TRR <- list()
for (p in names(POPL)) {
  e <- ato_mi_v31(D(p), PS, "outcome_primary", METHOD[[p]], B = 1, label = paste(p, "weights")); w <- Reduce(`+`, e$weights_by_imputation) / M
  raw <- RAW(p)
  mk <- function(coh, ww) rbind(trajectory_v32(coh, ww, creat_vals, "value", "Creatinine (mg/dL)", B = B_TRAJ),
                                trajectory_v32(coh, ww, bun_vals, "value", "Urea nitrogen (mg/dL)", B = B_TRAJ),
                                trajectory_v32(coh, ww, ratio_vals, "value", "Urea-to-creatinine ratio", B = B_TRAJ))
  TR[[p]] <- mk(raw, w)[, population := POPL[[p]]]
  late <- unique(merge(creat_vals, raw[, .(hadm_id, T0)], by = "hadm_id")[charttime >= T0 + 5 * 86400 & charttime < T0 + 8 * 86400, hadm_id])
  s <- raw$hadm_id %in% late
  TRR[[p]] <- mk(raw[s], w[s])[, population := paste0(POPL[[p]], ", creatinine on days 5-7")]
  TRR[[paste0(p, "_n")]] <- data.table(population = POPL[[p]], n = nrow(raw), n_restricted = sum(s), n_ptz = sum(s & raw$treatment == "PTZ"), n_comp = sum(s & raw$treatment != "PTZ"))
}
tr <- rbindlist(TR); trr <- rbindlist(TRR[c("early", "broad")])
tr[, marker := factor(marker, levels = c("Creatinine (mg/dL)", "Urea nitrogen (mg/dL)", "Urea-to-creatinine ratio"))]
trr[, marker := factor(marker, levels = levels(tr$marker))]
fwrite(tr, TAB("trajectories_v33.csv")); fwrite(trr, TAB("trajectories_restricted_d5_7_v33.csv"))
fwrite(rbindlist(TRR[c("early_n", "broad_n")]), TAB("trajectories_restricted_n_v33.csv"))
tr[, population := factor(population, levels = POPL)]
trr[, population := factor(population, levels = paste0(POPL, ", creatinine on days 5-7"))]
save_fig_v32(fig_trajectory_v33(tr), FIG("fig6_trajectories"), 19, 26)
save_fig_v32(fig_trajectory_v33(trr), FIG("efig_trajectories_restricted"), 19, 26)

cat("\n=== C.4 Sauvegardes, légendes, déviations, QA ===\n")
new <- is.na(rmt$rr_status)   # règle des 20 événements appliquée aux seules lignes ajoutées en phase C
rmt <- rbind(rmt[!new], apply_rr_rule_v33(rmt[new]), fill = TRUE)
fwrite(cohort_registry_table(), TAB("n_by_analysis_v32.csv"))
saveRDS(rmt, file.path(OUT, "results", "results_master.rds")); fwrite(rmt, file.path(OUT, "results", "results_master.csv"))
fwrite(rmt[, .(analysis_id, population, cohort_id, estimand, outcome, ps_method, m_imputations, n_boot, ci_method)], TAB("variance_methods_v32.csv"))
fwrite(rmt[, .(analysis_id, population, n, n_carb, rd, rd_ci_low, rd_ci_high, ci_half_width, mde80)][!is.na(rd)], TAB("precision_v32.csv"))
fwrite(rmt[, .(analysis_id, population, events_comp, rr_raw, rr_raw_ci_low, rr_raw_ci_high, rr_status)], TAB("rr_reporting_v33.csv"))
build_manuscript_numbers_json_v31(rmt, file.path(OUT, "results"))
dev <- fread(TAB("protocol_deviations_v33.csv"))[!id %in% c("D16", "D17")]
dev <- rbind(dev, data.table(id = c("D16", "D17"), version = "v3.3",
  deviation = c("Negative controls at 6 h and 12 h re-estimated in the same population (creatinine measured in both windows)",
                "Trajectories: urea-to-creatinine ratio added and sensitivity restricted to patients with a creatinine value on days 5-7"),
  reason = c("The 6 h population was a selected subgroup with very early creatinine, not comparable with the 12 h population",
             "Selection of later days (patients still in hospital and tested)"),
  where_reported = c("Negative controls", "Trajectories")), fill = TRUE)
fwrite(dev, TAB("protocol_deviations_v33.csv"))
dir.create(file.path(OUT, "figure_legends"), showWarnings = FALSE)
writeLines(legends_v33(rmt, cohort_registry_table(), function(f) fread(TAB(f))), file.path(OUT, "figure_legends", "legends.md"))

qa <- rbind(
  data.table(id = "QA-V33-4", check = "DAG: drawn edges identical to the dagitty edges; every edge has an origin and a destination box border and an arrowhead; no edge crosses another node",
             ok = qd$same_edges && qd$endpoints_on_borders && qd$arrows && length(qd$crossings) == 0,
             details = sprintf("%d model edges, %d drawn; crossings: %d", qd$n_model, qd$n_drawn, length(qd$crossings))),
  data.table(id = "QA-V33-C2", check = "Negative controls at 6 h and 12 h estimated in the same registered population (identical N)",
             ok = all(rmt[grepl("_nc_a6_same$", analysis_id), n] == rmt[grepl("_nc_a12_same$", analysis_id), n]),
             details = paste(sprintf("%s N=%d", rmt[grepl("_nc_a6_same$", analysis_id), cohort_id], rmt[grepl("_nc_a6_same$", analysis_id), n]), collapse = "; ")),
  data.table(id = "QA-V33-C3", check = "Trajectories include the urea-to-creatinine ratio and a days 5-7 restricted sensitivity",
             ok = "Urea-to-creatinine ratio" %in% tr$marker && nrow(trr) > 0, details = ""),
  data.table(id = "QA-V33-2", check = "No risk ratio reported with fewer than 20 events in the comparator arm (after phase C rows)",
             ok = rmt[!is.na(rr) & !grepl("^ordinal_OR", estimand), all(!is.na(events_comp) & events_comp >= 20)],
             details = sprintf("%d rows with RR not estimated", sum(grepl("^not estim", rmt$rr_status)))))
qa[, status := fifelse(ok, "PASS", "FAIL")][, ok := NULL]
fwrite(qa, TAB("qa_phaseC_v33.csv")); print(qa[, .(id, status, details)])
cat(sprintf("PHASE C v3.3 (données) TERMINÉE (%.1f min)\n", as.numeric(difftime(Sys.time(), T_START, units = "mins"))))
